private runtimeIdentity(attempt: A2AAttempt, live: Awaited<ReturnType<GateRuntime["readThread"]>>) {
  const identity = live.runtime_identity;
  requireGate(identity && identity.thread === attempt.thread_id && typeof identity.launch === "string" &&
    identity.launch.length > 0 && Number.isInteger(identity.shell_pid) && identity.shell_pid > 0 &&
    (identity.leader_pid === null || Number.isInteger(identity.leader_pid) && identity.leader_pid > 0) &&
    (identity.native_session === null || typeof identity.native_session === "string" && identity.native_session.length > 0),
    "identity_conflict", { attempt, live });
  return identity;
}

}
private bindObservedIdentity(attempt: A2AAttempt, live: Awaited<ReturnType<GateRuntime["readThread"]>>) {
  this.checkThread(attempt, live);
  const bound = attempt.runtime_identity!, identity = live.runtime_identity;
  const changed = bound.leader_pid === null && identity.leader_pid !== null ||
    bound.native_session === null && identity.native_session !== null;
  if (bound.leader_pid === null) bound.leader_pid = identity.leader_pid;
  if (bound.native_session === null) bound.native_session = identity.native_session;
  return changed;

// Finish an already-started gate under its lock, then stop before the
// next gate. Shutdown must not advance a waiting run to acceptance.
requireGate(!this.shuttingDown, "daemon_stopping");

let requestsDrained: (() => void) | undefined;
const activityFinished = () => {
  activeRequests--;
  if (activeRequests === 0) { requestsDrained?.(); requestsDrained = undefined; }
};

// Requests and deferred receipt writes retain their stores until their
// final results are durable. run observes beginShutdown at safe boundaries.
if (activeRequests > 0) await new Promise<void>((resolve) => { requestsDrained = resolve; });

const wait = input.command === "run" ? input.wait_seconds : undefined;
const deadline = typeof wait === "number" && Number.isSafeInteger(wait) && wait > 0
  ? Math.min(2_147_483_647, Math.max(120_000, wait * 1000 + 120_000)) : 120_000;
socket.setTimeout(deadline, () => socket.destroy(new Error("daemon request deadline; outcome unknown")));

export interface A2ARuntimeIdentity {
  launch: string;
  thread: string;
  shell_pid: number;
  leader_pid: number | null;
  native_session: string | null;
}

const owned = new Map<string, { launch: string; shell_pid: number }>();
const controlledRuntime = {
  ...runtime,
  createThread: async (task: any, attempt: any) => {
    await runtime.createThread(task, attempt);
    owned.set(attempt.thread_id, { launch: randomUUID(), shell_pid: 10000 + owned.size });
  },
  readThread: async (thread: string) => {
    const live = await runtime.readThread(thread), owner = owned.get(thread);
    if (!owner) throw new Error("Controlled runtime owner was not created by this host");
    // This old external fixture uses its turn token as the owner generation:
    // leader-changed replaces it; helper-joins leaves it unchanged. No actual
    // native session or CLI PID is claimed by this synthetic runtime.
    return { ...live, runtime_identity: { launch: owner.launch, thread, shell_pid: owner.shell_pid,
      leader_pid: live.turn ? 20000 : null, native_session: live.turn } };
  },
};
